$max = intval(fgets(STDIN));
$nums = [];
while ($row = fgetcsv(STDIN, escape: ',')) {
    [$n, $name] = $row;
    $nums[$n] = $name;
}

foreach (range(1, $max) as $i) {
    $s = '';
    foreach ($nums as $n => $name) {
        if ($i % $n === 0) {
            $s = $s . $name;
        }
    }
    if ($s === '') {
        echo $i, "\n";
    } else {
        echo $s, "\n";
    }
}
